/* Original sprite art REUSED from Jensen vs Alice (main branch).
   Alice's existing idle + four full-resolution running frames are retained.
   Kimberly shares the same pixel fidelity via a per-pixel palette variant, not rectangle art.
   Combat geometry remains independent from artwork. */
const originalAliceData=["","","","",""];
const art={alice:[],kimberly:[]};
function makeKimberlyVariant(image){
  const off=document.createElement('canvas');off.width=image.naturalWidth;off.height=image.naturalHeight;
  const oc=off.getContext('2d',{willReadFrequently:true});oc.drawImage(image,0,0);
  const pix=oc.getImageData(0,0,off.width,off.height),d=pix.data;
  for(let i=0;i<d.length;i+=4){
    if(d[i+3]<10)continue;
    let r=d[i],g=d[i+1],b=d[i+2],max=Math.max(r,g,b),min=Math.min(r,g,b);
    // Crimson/pink dress into royal blue, keeping the sprite's original detailed shading.
    if(r>65&&r>g*1.35&&r>b*1.16&&r-g>34&&b>28&&(max-min)>44){
      let v=(r+g+b)/3;
      d[i]=Math.min(255,Math.round(v*.46+23));
      d[i+1]=Math.min(255,Math.round(v*.9+51));
      d[i+2]=Math.min(255,Math.round(v*1.18+88));
    }
    // Original auburn hair gets a distinct warm chestnut-gold palette.
    // Restrict to upper part of the sprite to preserve boots and accessories.
    else if((i/4/off.width)<off.height*.60&&r>28&&r<165&&g<116&&b<112&&r>g*1.15&&r>b*1.1){
      d[i]=Math.min(255,Math.round(r*1.20+14));
      d[i+1]=Math.min(255,Math.round(g*1.23+13));
      d[i+2]=Math.min(255,Math.round(b*.78+3));
    }
  }
  oc.putImageData(pix,0,0);return off;
}
originalAliceData.forEach((data,i)=>{
  const im=new Image();im.onload=()=>{
    art.alice[i]=im;
    try{art.kimberly[i]=makeKimberlyVariant(im)}catch{art.kimberly[i]=im}
    if(i===0&&typeof portraits==='function')portraits();
  };
  im.src='data:image/webp;base64,'+data;
});

/* Kimberly's art is authored from the user-provided reference image, NOT an Alice recolor. */
const kimArt={idle:new Image(),punch:new Image()};
